public final class TransfuserClientScene {
 public static final BlockPos P=new BlockPos(67208,162,0),Q=P.south(5);public static volatile boolean ready,photo,rotated;static ServerPlayer actor;static int ticks,stage;
 @SubscribeEvent public static void join(EntityJoinLevelEvent e){if(System.getProperty("thaumcraft.bookProbe","").equals("transfuser-client")&&e.getEntity() instanceof ServerPlayer p)actor=p;}
 static void label(ServerLevel l,String text,double x,double y,double z){var a=net.minecraft.core.registries.BuiltInRegistries.ENTITY_TYPE.getValue(net.minecraft.resources.Identifier.parse("minecraft:armor_stand")).create(l,EntitySpawnReason.COMMAND);a.setPos(x,y,z);a.setInvisible(true);a.setNoGravity(true);a.setCustomName(net.minecraft.network.chat.Component.literal(text));a.setCustomNameVisible(true);l.addFreshEntity(a);}
 @SubscribeEvent public static void tick(TickEvent.ServerTickEvent.Post e){if(actor==null)return;var l=actor.level();if(stage==0&&++ticks>80){for(int x=-3;x<=8;x++)for(int z=-3;z<=10;z++)TransfuserProbe.set(l,P.offset(x,-2,z),Blocks.SMOOTH_STONE.defaultBlockState());actor.gameMode.changeGameModeForPlayer(GameType.CREATIVE);actor.getAbilities().flying=false;actor.onUpdateAbilities();actor.getInventory().clearContent();actor.setItemInHand(net.minecraft.world.InteractionHand.MAIN_HAND,new ItemStack(EssentiaContent.RESONATOR.get()));TransfuserProbe.tube(l,P.west(),TubeBlock.Kind.BUFFER,Map.of("aer",10),"");TransfuserProbe.device(l,P,Direction.EAST,true);TransfuserProbe.jar(l,P.east(4),"",0,"");TransfuserProbe.device(l,Q,Direction.EAST,false);TransfuserProbe.tube(l,Q.west(),TubeBlock.Kind.FILTER,Map.of(),"ignis");TransfuserProbe.tube(l,Q.west().south(),TubeBlock.Kind.FILTER,Map.of(),"ignis");TransfuserProbe.jar(l,Q.west().south().below(),"",0,"ignis");for(var support:List.of(P,P.west(),P.east(4),Q,Q.east(4),Q.west()))TransfuserProbe.set(l,support.below(),Blocks.STONE_BRICKS.defaultBlockState());TransfuserProbe.jar(l,Q.east(4),"ignis",10,"");actor.teleportTo(l,Q.getX()+.5,Q.getY()-1,Q.getZ()+3.4,Set.of(),180,20,true);actor.lookAt(net.minecraft.commands.arguments.EntityAnchorArgument.Anchor.EYES,Vec3.atCenterOf(Q).add(0,.2,0));stage=1;ticks=0;return;}if(stage==1){if(++ticks>600)throw new AssertionError("Live transfuser scene did not finish");var fill=(TransfuserEntity)l.getBlockEntity(P);var empty=(TransfuserEntity)l.getBlockEntity(Q);var in=(TubeEntity)l.getBlockEntity(P.west());var filled=(AlchemyMachine)l.getBlockEntity(P.east(4));var src=(AlchemyMachine)l.getBlockEntity(Q.east(4));var rear=(TubeEntity)l.getBlockEntity(Q.west());var connector=(TubeEntity)l.getBlockEntity(Q.west().south());var dst=(AlchemyMachine)l.getBlockEntity(Q.west().south().below());if(fill.snapshot().transferred()<5||empty.snapshot().transferred()<5||dst.total()<5)return;TransfuserProbe.check(in.total()+filled.total()+(fill.snapshot().pending().isEmpty()?0:1)==10,"Live filler did not conserve ten units");TransfuserProbe.check(src.total()+rear.total()+connector.total()+dst.total()+(empty.snapshot().pending().isEmpty()?0:1)==10,"Live emptying did not conserve ten units");e.server().tickRateManager().setFrozen(true);ready=true;stage=2;thaumcraft.Thaumcraft.LOGGER.info("TRANSFUSER71_CLIENT_FLOW_OK: real tickers, filling {} and emptying {}, ten units conserved per row",fill.snapshot().transferred(),empty.snapshot().transferred());}if(stage==3&&Files.exists(Path.of("../work/transfuser71-camera"))){try{String raw=Files.readString(Path.of("../work/transfuser71-camera")).trim();Files.delete(Path.of("../work/transfuser71-camera"));var values=raw.split(" ");actor.teleportTo(l,P.getX()+Double.parseDouble(values[0]),P.getY()+Double.parseDouble(values[1]),P.getZ()+Double.parseDouble(values[2]),Set.of(),135,18,true);actor.lookAt(net.minecraft.commands.arguments.EntityAnchorArgument.Anchor.EYES,Vec3.atCenterOf(P.south(2).east(2)));}catch(Exception ex){throw new RuntimeException(ex);}}if(stage==2&&l.getBlockState(Q).getValue(TransfuserBlock.FACING)!=Direction.EAST){rotated=true;actor.getAbilities().flying=true;actor.onUpdateAbilities();l.setBlockAndUpdate(Q,l.getBlockState(Q).setValue(TransfuserBlock.FACING,Direction.EAST));actor.teleportTo(l,P.getX()+9,P.getY()+4,P.getZ()+12,Set.of(),135,18,true);actor.lookAt(net.minecraft.commands.arguments.EntityAnchorArgument.Anchor.EYES,Vec3.atCenterOf(P.south(2).east(2)));var filled=(AlchemyMachine)l.getBlockEntity(P.east(4));var dst=(AlchemyMachine)l.getBlockEntity(Q.west().south().below());label(l,"Llenado: "+filled.total()+" / 10",P.getX()+3,P.getY()-.6,P.getZ());label(l,"Vaciado: "+dst.total()+" / 10",Q.getX()+1,Q.getY()-.6,Q.getZ());photo=true;stage=3;thaumcraft.Thaumcraft.LOGGER.info("TRANSFUSER71_CLIENT_ROTATE_OK: native sneak-use rotated nozzle; photo ready");}}
}
